def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    from collections import deque

    MOD = 1_000_000_007
    if n == 0:
        return 1
    if not banned:
        return pow(len(alphabet), n, MOD)

    char_index = {ch: i for i, ch in enumerate(alphabet)}
    width = len(alphabet)

    transitions = [[-1] * width]
    failure = [0]
    forbidden = [False]

    for word in banned:
        state = 0
        for ch in word:
            c = char_index[ch]
            if transitions[state][c] == -1:
                transitions[state][c] = len(transitions)
                transitions.append([-1] * width)
                failure.append(0)
                forbidden.append(False)
            state = transitions[state][c]
        forbidden[state] = True

    queue = deque()
    for c in range(width):
        child = transitions[0][c]
        if child == -1:
            transitions[0][c] = 0
        else:
            queue.append(child)

    while queue:
        state = queue.popleft()
        fallback = failure[state]
        forbidden[state] |= forbidden[fallback]

        for c in range(width):
            child = transitions[state][c]
            if child == -1:
                transitions[state][c] = transitions[fallback][c]
            else:
                failure[child] = transitions[fallback][c]
                queue.append(child)

    safe_states = [
        state for state in range(len(transitions)) if not forbidden[state]
    ]
    indices = {state: i for i, state in enumerate(safe_states)}
    size = len(safe_states)

    matrix = [[0] * size for _ in range(size)]
    for state in safe_states:
        row = matrix[indices[state]]
        for target in transitions[state]:
            if not forbidden[target]:
                row[indices[target]] += 1

    counts = [0] * size
    counts[indices[0]] = 1

    while n:
        if n & 1:
            updated = [0] * size
            for i, count in enumerate(counts):
                if count:
                    for j, ways in enumerate(matrix[i]):
                        if ways:
                            updated[j] += count * ways
            counts = [value % MOD for value in updated]

        n >>= 1
        if not n:
            break

        squared = [[0] * size for _ in range(size)]
        for i, row in enumerate(matrix):
            result_row = squared[i]
            for k, left in enumerate(row):
                if left:
                    for j, right in enumerate(matrix[k]):
                        if right:
                            result_row[j] += left * right
            for j in range(size):
                result_row[j] %= MOD
        matrix = squared

    return sum(counts) % MOD
